export enum SandboxEnvironment {
	AGENT = 'AGENT',
	BUILDER = 'BUILDER',
	APP_STORE_PUBLISH = 'APP_STORE_PUBLISH',
	SCREENSHOT = 'SCREENSHOT',
	BUNDLER = 'BUNDLER'
}

export const TMP_STARTING_ID = 'tmp-starting'

export enum DevServerStatus {
	/**
	 * The machine is booting up.
	 */
	BOOTING = 'BOOTING',
	/**
	 * The machine is booted and it is being prepared or the the server is starting.
	 */
	STARTING = 'STARTING',
	/**
	 * The server is running and ready to accept connections.
	 */
	RUNNING = 'RUNNING',

	/**
	 * The server is beig stopped.
	 */
	STOPPING = 'STOPPING',

	/**
	 * The server is stopped.
	 */
	STOPPED = 'STOPPED'
}
export const getDevServerIdFromProjectGroup = ({
	projectGroupId,
	environment
}: {
	projectGroupId: string
	environment: SandboxEnvironment
}) => {
	return `${projectGroupId}:${environment}`
}

export const getDevServerIdFromProjectGroupRevision = ({
	projectGroupRevisionId,
	environment
}: {
	projectGroupRevisionId: string
	environment: SandboxEnvironment
}) => {
	return `${projectGroupRevisionId}:revision:${environment}`
}

export const getDevServerIdFromProjectGroupAndRevision = ({
	projectGroupId,
	projectGroupRevisionId,
	environment
}: {
	projectGroupId: string
	projectGroupRevisionId: string
	environment: SandboxEnvironment
}) => {
	return `${projectGroupId}:${projectGroupRevisionId}:${environment}`
}

export function getDevServerId({
	projectGroupId,
	projectGroupRevisionId,
	environment
}: {
	projectGroupId: string
	projectGroupRevisionId: string | null
	environment: SandboxEnvironment
}): string

export function getDevServerId({
	projectGroupId,
	projectGroupRevisionId,
	environment
}: {
	projectGroupId: string | null
	projectGroupRevisionId: string
	environment: SandboxEnvironment
}): string

export function getDevServerId({
	projectGroupId,
	projectGroupRevisionId,
	environment
}: {
	projectGroupId: string
	projectGroupRevisionId: string
	environment: SandboxEnvironment
}): string

export function getDevServerId({
	projectGroupId,
	projectGroupRevisionId,
	environment
}: {
	projectGroupId: string | null
	projectGroupRevisionId: string | null
	environment: SandboxEnvironment
}): string {
	if (environment === SandboxEnvironment.AGENT) {
		if (projectGroupId && projectGroupRevisionId) {
			return getDevServerIdFromProjectGroupAndRevision({
				projectGroupId,
				projectGroupRevisionId,
				environment
			})
		}

		throw new Error(
			'projectGroupId and projectGroupRevisionId are required for the sandbox environment: AGENT'
		)
	}

	if (projectGroupId) {
		return getDevServerIdFromProjectGroup({
			projectGroupId,
			environment
		})
	}

	if (projectGroupRevisionId) {
		return getDevServerIdFromProjectGroupRevision({
			projectGroupRevisionId,
			environment
		})
	}

	// This should never happen
	throw new Error(
		'One of projectGroupId or projectGroupRevisionId must be provided'
	)
}
